using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using V15Voice;
public static class InlineAiUiTests {
 static int count,code;static string folder;
 static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void S(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static void Check(bool v,string name){if(!v)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Capture(Form f,string name){Application.DoEvents();f.Refresh();using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.Location,Point.Empty,f.Size);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation",name+".png"));}}
 sealed class E:KokoroEngine {public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){int n=(int)(System.Text.RegularExpressions.Regex.Matches(text,@"\b\w+\b").Count*.30/speed*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,n).Select(i=>i<n-1200?(short)(5000*Math.Sin(i*.06)):(short)0).ToArray()};}}
 sealed class W:ITextRewriter {public int Id=1;public int Calls;public bool Slow,Entered;public string Rewrite(string p,Func<bool> cancel,Action<string> a){Entered=true;while(Slow){if(cancel())throw new OperationCanceledException();Thread.Sleep(20);}Calls++;return LocalAi.Json(new AiRewriteText{cues=new List<AiCueText>{new AiCueText{id=Id,text=Id==1?"John could not believe the door had finally opened.":"He could not believe the door had finally opened."}}});}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();folder=Path.Combine(Path.GetTempPath(),"V15 inline UI "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var f=new MainForm();f.Shown+=async(s,e)=>{try{
  var settings=new VoiceSettings{Mode=0,Key="K:3",AiMode=0,AiFixShort=false,Breathing=2,Slow=false,Normalize=false};C(f,"Apply",settings);
  string file=Path.Combine(folder,"story.srt");File.WriteAllText(file,"1\n00:00:00,000 --> 00:00:03,300\nJohn was standing there for a very long time because the door had finally opened.\n\n2\n00:00:03,450 --> 00:00:06,750\nHe was waiting there for a very long time because the door had finally opened.\n\n3\n00:00:06,900 --> 00:00:10,200\nThis small detail changes the whole story for everyone.\n");C(f,"LoadFile",file);string originalHash=StateFiles.Hash(file);
  var cues=(List<Cue>)F(f,"cues");cues[0].Status="QUÁ DÀI: +1,200s";cues[1].Status="QUÁ DÀI: +0,900s";cues[2].Status="Đạt";C(f,"Populate");var grid=(DataGridView)F(f,"grid");
  Check(grid.Rows[0].Cells["aiFix"] is DataGridViewButtonCell&&Convert.ToString(grid.Rows[0].Cells["aiFix"].Value)=="AI sửa câu","Timing error has an actionable repair button in the main row");
  Check(grid.Rows[2].Cells["aiFix"] is DataGridViewTextBoxCell&&String.IsNullOrEmpty(Convert.ToString(grid.Rows[2].Cells["aiFix"].Value)),"Passing row has no misleading empty repair button");
  Check(((ComboBox)F(f,"aiMode")).SelectedIndex==0,"Inline repair is available while global automatic AI is off");
  Check((bool)C(f,"ShowInlineTimingFailure",new Exception("Có 2 câu vẫn vượt timeline sau khi tăng đến giới hạn."),null),"Timing render failure is shown at the rows without a blocking error dialog");
  Check(!(bool)C(f,"ShowInlineTimingFailure",new Exception("CUDA missing model"),null),"Real engine faults keep their diagnostic error handling");
  foreach(var size in new[]{new Size(1440,960),new Size(1100,740)}){f.Size=size;f.Location=Point.Empty;Application.DoEvents();C(f,"ResizeInlineAiColumns");Application.DoEvents();var r=grid.GetCellDisplayRectangle(grid.Columns["aiFix"].Index,0,false);Console.WriteLine("CELL "+size+" "+r+" grid "+grid.ClientSize);Check(r.Width>=100&&r.Right<=grid.ClientSize.Width&&r.Left>=0,"Repair button is visible without horizontal scroll at "+size);Check(grid.Columns["text"].Width>=100,"Script remains editable at "+size);Check(grid.Rows[0].Height>=44&&grid.Columns["text"].InheritedStyle.WrapMode==DataGridViewTriState.True,"Rows retain readable height and script wrapping at "+size);Capture(f,"inline-ai-before-"+size.Width);}
  f.Size=new Size(1440,960);Application.DoEvents();settings=(VoiceSettings)C(f,"CaptureSettings");var p=AiRepairSession.Open(file,cues,folder,settings,false);var writer=new W();Func<string,KokoroEngine> factory=role=>new E{Root=folder,VoiceName="Fixture "+role,Archive=new SpeechArchive(Path.Combine(folder,"cache"))};
  var actualFactory=(Func<string,KokoroEngine>)C(f,"AiFactory",settings);S(f,"inlineAiFingerprint",C(f,"AiVoiceFingerprint",settings,actualFactory));
  var task=(Task)C(f,"RunInlineAi",p,1,writer,factory);Check((bool)F(f,"busy")&&!((Control)F(f,"render")).Enabled&&((Control)F(f,"cancel")).Enabled,"Repair locks rendering and leaves Stop available");await task;
  cues=(List<Cue>)F(f,"cues");Check(cues[0].Text.Contains("could not believe")&&Convert.ToString(grid.Rows[0].Cells["aiFix"].Value)=="Hoàn tác","Successful one-row repair updates wording and exposes Undo");
  Check(cues[1].Text.StartsWith("He was waiting")&&Convert.ToString(grid.Rows[1].Cells["aiFix"].Value)=="AI sửa câu"&&cues[2].Status=="Đạt","Other error and passing rows are preserved");
  Check(!(bool)F(f,"busy")&&((Control)F(f,"render")).Enabled&&((Label)F(f,"status")).Text.Contains("TẠO VOICE"),"After repair UI unlocks and points directly to WAV export");
  Check(F(f,"pendingAi")==p&&File.Exists((string)F(f,"lastVoiceReport")),"Inline repair attaches its history to the next full render");
  Capture(f,"inline-ai-after-1440");await (Task)C(f,"RepairInlineCue",0);cues=(List<Cue>)F(f,"cues");Check(cues[0].Text.StartsWith("John was standing")&&Convert.ToString(grid.Rows[0].Cells["aiFix"].Value)=="Áp dụng lại","Clicking Undo restores original wording with a direct reapply action");
  var slow=new W{Id=2,Slow=true};task=(Task)C(f,"RunInlineAi",p,2,slow,factory);for(int i=0;i<200&&!slow.Entered;i++)await Task.Delay(10);Check(slow.Entered,"Second-row repair reached the AI stage");C(f,"CancelTasks");await task;cues=(List<Cue>)F(f,"cues");Check(cues[1].Text.StartsWith("He was waiting")&&!(bool)F(f,"busy"),"Stop cancels the selected repair without applying partial wording");
  Check(StateFiles.Hash(file)==originalHash,"All inline UI actions preserve original SRT bytes");
  ((ComboBox)F(f,"mode")).SelectedIndex=1;C(f,"RefreshInlineAi");Check(grid.Rows.Cast<DataGridViewRow>().All(r=>r.Cells["aiFix"] is DataGridViewTextBoxCell),"Flexible mode hides fixed-timeline repair actions");
  ((ComboBox)F(f,"mode")).SelectedIndex=2;C(f,"RefreshInlineAi");Check(Convert.ToString(grid.Rows[1].Cells["aiFix"].Value)=="AI sửa chặng","V15.6 button clearly says it repairs the whole stage");
  Console.WriteLine("TOTAL INLINE AI UI "+count+" passed. Fixture voice/rewriter on Mono/Linux.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
